// Before: the UI does everything.
@Composable
fun WeatherScreen(api: WeatherApi) {
    var text by remember { mutableStateOf("Loading...") }
    LaunchedEffect(Unit) {
        text = try { "${api.today("Cairo").tempC}°C" } catch (e: Exception) { "Error" }
    }
    Text(text)
}

// After: each layer does one job.
class WeatherRepository @Inject constructor(private val api: WeatherApi) {
    suspend fun today(city: String): Result<Weather> = runCatching { api.today(city).toDomain() }
}

@HiltViewModel
class WeatherViewModel @Inject constructor(private val repo: WeatherRepository) : ViewModel() {
    private val _state = MutableStateFlow<WeatherUiState>(WeatherUiState.Loading)
    val state = _state.asStateFlow()
    init { load() }
    fun load() = viewModelScope.launch {
        _state.value = repo.today("Cairo").fold({ WeatherUiState.Ready(it) }, { WeatherUiState.Error })
    }
}

