sealed interface CatalogueUiState {
    data object Loading : CatalogueUiState
    data class Ready(val items: List<Item>, val query: String) : CatalogueUiState
    data class Failed(val message: String) : CatalogueUiState
}

@HiltViewModel
class CatalogueViewModel @Inject constructor(repo: CatalogueRepository, saved: SavedStateHandle) : ViewModel() {
    private val query = saved.getStateFlow("query", "")

    val state: StateFlow<CatalogueUiState> = combine(repo.observeItems(), query) { items, q ->
        CatalogueUiState.Ready(items.filter { it.name.contains(q, ignoreCase = true) }, q) as CatalogueUiState
    }
        .catch { emit(CatalogueUiState.Failed("Couldn't load the catalogue")) }
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), CatalogueUiState.Loading)
}

class MainDispatcherRule(private val dispatcher: TestDispatcher = UnconfinedTestDispatcher()) : TestWatcher() {
    override fun starting(description: Description) = Dispatchers.setMain(dispatcher)
    override fun finished(description: Description) = Dispatchers.resetMain()
}

class OrdersViewModelTest {
    @get:Rule val main = MainDispatcherRule()
    private val repo = FakeOrdersRepository(listOf(order(1, paid = true), order(2, paid = false)))

    @Test fun filterShowsOnlyPaidOrders() = runTest {
        val vm = OrdersViewModel(repo)
        backgroundScope.launch { vm.state.collect {} }       // keep stateIn active
        vm.onFilterChange(OrderFilter.PAID)
        assertEquals(listOf(1), vm.state.value.orders.map { it.id })
    }

    @Test fun refreshFailureShowsMessage() = runTest {
        repo.failNextRefresh = true
        val vm = OrdersViewModel(repo)
        backgroundScope.launch { vm.state.collect {} }
        vm.onRefresh()
        assertNotNull(vm.state.value.errorMessage)
    }
}

interface OrdersRepository {
    fun observeOrders(): Flow<List<Order>>
    suspend fun refresh(): Result<Unit>
}

class DefaultOrdersRepository @Inject constructor(
    private val dao: OrderDao,
    private val api: OrdersApi,
) : OrdersRepository {
    override fun observeOrders() = dao.observeAll().map { rows -> rows.map(OrderEntity::toDomain) }

    override suspend fun refresh() = runCatching {
        val remote = api.orders()                       // List<OrderDto>
        dao.replaceAll(remote.map(OrderDto::toEntity))   // one transaction
    }
}

class FakeOrdersRepository(initial: List<Order> = emptyList()) : OrdersRepository {
    private val orders = MutableStateFlow(initial)
    var failNextRefresh = false
    var refreshCalls = 0

    override fun observeOrders(): Flow<List<Order>> = orders

    override suspend fun refresh(): Result<Unit> {
        refreshCalls++
        if (failNextRefresh) { failNextRefresh = false; return Result.failure(IOException("offline")) }
        return Result.success(Unit)
    }

    fun emit(list: List<Order>) { orders.value = list }       // simulate new data from the database
}

class AppContainer(context: Context) {
    private val retrofit = Retrofit.Builder().baseUrl(BuildConfig.API_URL)
        .addConverterFactory(Json.asConverterFactory("application/json".toMediaType())).build()
    private val db = Room.databaseBuilder(context, ShopDatabase::class.java, "shop.db").build()
