// I: callers that only read don't see write methods.
interface ProductReader { fun observe(id: Int): Flow<Product?> }
interface ProductWriter { suspend fun save(product: Product) }
class ProductRepositoryImpl @Inject constructor(private val dao: ProductDao) : ProductReader, ProductWriter {
    override fun observe(id: Int) = dao.observe(id).map { it?.toDomain() }
    override suspend fun save(product: Product) = dao.upsert(product.toEntity())
}

