class PlaceOrderUseCase @Inject constructor(
    private val cart: CartRepository,
    private val orders: OrdersRepository,
    private val calculateTotal: CalculateTotalUseCase,
) {
    suspend operator fun invoke(addressId: Int, coupon: Coupon?): Result<OrderId> {
        val items = cart.current()
        if (items.isEmpty()) return Result.failure(EmptyCartException())
        val total = calculateTotal(items, coupon)
        return orders.place(items, addressId, total).onSuccess { cart.clear() }
    }
}

class PlaceOrderUseCaseTest {
    @Test fun emptyCartFailsWithoutCallingTheServer() = runTest {
        val orders = FakeOrdersRepository()
        val result = PlaceOrderUseCase(FakeCartRepository(emptyList()), orders, CalculateTotalUseCase { 0 })(1, null)
        assertTrue(result.exceptionOrNull() is EmptyCartException)
        assertEquals(0, orders.placeCalls)
    }
}

class ProfileRepository @Inject constructor(private val api: ProfileApi, private val dao: ProfileDao) {
    suspend fun refresh(): Result<Unit> = safeCall {
        dao.upsert(api.me().toEntity())
    }
}

@HiltViewModel
class ProfileViewModel @Inject constructor(private val repo: ProfileRepository) : ViewModel() {
    private val _message = MutableStateFlow<String?>(null)
    val message = _message.asStateFlow()

    fun refresh() = viewModelScope.launch {
        repo.refresh().onFailure { e ->
            val error = (e as? DataException)?.error ?: DataError.Unknown(e)
            if (error is DataError.Unknown) Firebase.crashlytics.recordException(e)
            _message.value = error.userMessage()
        }
    }
}

@Composable
fun FeedContent(state: FeedUiState, onRetry: () -> Unit) {
    when {
        state.items.isEmpty() && state.error != null ->              // nothing to show: full-screen error
            ErrorState(message = state.error, actionLabel = "Try again", onAction = onRetry)
        state.items.isEmpty() && state.loading -> FullScreenLoading()
        else -> Column {
            if (state.error != null) OfflineBanner(state.error, onRetry)   // keep showing saved items
            FeedList(state.items)
        }
    }
}

